import joblib
from typing import Dict

def sentiment(text: str) -> float:
    model = joblib.load('models/sentiment_v3.pkl')
    prediction = model.predict([text])[0]
    return round(float(prediction), 3)

def median(nums: list) -> float:
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return float(nums_sorted[mid])

def second_largest(nums: list) -> int:
    unique_nums = list(set(nums))
    if len(unique_nums) < 2:
        raise ValueError("Not enough distinct elements")
    unique_nums.sort()
    return unique_nums[-2]

def dedupe(xs: list) -> list:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def is_palindrome(s: str) -> bool:
    cleaned = ''.join(char.lower() for char in s if char.isalnum())
    return cleaned == cleaned[::-1]

def word_count(text: str) -> dict:
    words = text.split()
    cleaned_words = []
    for word in words:
        cleaned = word.strip('.,!?
')
        if cleaned:
            cleaned_words.append(cleaned.lower())
    return dict(word.count(cleaned_words.count(word)) for word in set(cleaned_words))

def parse_price(s: str) -> float:
    import re
    match = re.search(r'\$(\d{1,3}(,\d{3})*\.\d{2})', s)
    if not match:
        raise ValueError('Invalid price format')
    price_str = match.group(1).replace(',', '')
    return float(price_str)

def c_to_f(c: float) -> float:
    f = c * 9/5 + 32
    return round(f, 1)

def normalize_phone(s: str) -> str:
    s = ''.join(c for c in s if c.isdigit())
    if len(s) == 10:
        return f'({s[:3]}) {s[3:6]}-{s[6:]}'
    return s

def roman_to_int(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += current_char + str(count)
            current_char = char
            count = 1
    result += current_char + str(count)
    return result

def fizzbuzz(n: int) -> list:
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

